// decodeLayerRPCRequest owns a fresh state for the complete transparent
// wrapper chain. Exact nested TypeRef bindings therefore cannot leak between
// requests or collide merely because different wrappers both call a slot X.
func decodeLayerRPCRequest(profile LayerProfile, b *bin.Buffer, limits LayerDecodeLimits, callback LayerRPCAdmissionPreflight, fieldCallbacks []LayerRPCAdmissionFieldPreflight, unknownAdapter layerRPCUnknownMethodAdapter, profileAdmission layerRPCProfileAdmissionMode) (layerDecodedRPCRequest, error) {
	if b == nil {
		return layerDecodedRPCRequest{}, &LayerCodecError{Operation: "admit RPC request", Profile: profile, Reason: "nil buffer"}
	}
	state, err := newLayerCodecDecodeState(profile, b.Len(), limits.layerCodecDecodeLimits())
	if err != nil {
		return layerDecodedRPCRequest{}, err
	}
	fieldRunner := layerRPCAdmissionFieldRunner{callbacks: fieldCallbacks}
	if len(fieldCallbacks) != 0 {
		state.rpcAdmission = &fieldRunner
	}
	preflight := layerRPCAdmissionPreflightRunner{
		callback:         callback,
		fields:           state.rpcAdmission,
		unknownAdapter:   unknownAdapter,
		profileAdmission: profileAdmission,
		admissionProfile: profile,
	}
	preflight.adaptCanonical = func(targetProfile LayerProfile, canonical *bin.Buffer) (LayerOutboundCall, error) {
		request, err := prepareLayerRPCRequest(LayerProfileCanonical, canonical, limits, nil, fieldCallbacks, nil, layerRPCProfileFrozen)
		if err != nil {
			return LayerOutboundCall{}, err
		}
		return request.PrepareOutbound(targetProfile)
	}
	decoded, err := decodeLayerRPCRequestState(profile, b, state, &preflight, 0)
	if err != nil {
		return layerDecodedRPCRequest{}, err
	}
	if atomic.LoadUint32(&preflight.called) != 1 {
		return layerDecodedRPCRequest{}, &LayerCodecError{Operation: "admit RPC request", Profile: profile, Reason: "terminal RPC route omitted admission preflight"}
	}
	if preflight.explicitProfileSet {
		if decoded.call.Profile() != preflight.explicitProfile {
			return layerDecodedRPCRequest{}, &LayerCodecError{Operation: "admit RPC request", Profile: decoded.call.Profile(), Semantic: decoded.call.Method(), WireID: decoded.call.WireID(), Reason: fmt.Sprintf("terminal profile %d differs from explicit invokeWithLayer profile %d", decoded.call.Profile(), preflight.explicitProfile)}
		}
		decoded.explicitProfile = preflight.explicitProfile
		decoded.profileEvidence = true
	}
	return decoded, nil
}

