func isGeneratedLayerRPCWrapperWireID(id uint32) bool {
	switch id {
	case 0x0dae54f8:
		return true
	case 0x1df92984:
		return true
	case 0x365275f2:
		return true
	case 0x3dc4b4f0:
		return true
	case 0xaca9fd2e:
		return true
	case 0xadbb0f94:
		return true
	case 0xbf9459b7:
		return true
	case 0xc1cd5ea9:
		return true
	case 0xcb9f372d:
		return true
	case 0xda9b0d0d:
		return true
	case 0xdd289f8e:
		return true
	default:
		return false
	}
}

