// layerRPCHandler is registered once per semantic method. Exact profile wire
// IDs are resolved by the generated request decoder before this map is read.
type layerRPCHandler func(context.Context, bin.Object) (any, error)

// layerRPCCanonicalResultEncoder restores the historical ServerDispatcher
// Handle result shape on demand. Exact multi-layer dispatch keeps the raw
// handler value so it can encode through the admitted result TypeRef without
// allocating a canonical-only box on the hot path.
type layerRPCCanonicalResultEncoder func(any) (bin.Encoder, error)

type layerRPCRegisteredHandler struct {
	invoke          layerRPCHandler
	canonicalResult layerRPCCanonicalResultEncoder
}

func layerRPCDirectCanonicalResult(value any) (bin.Encoder, error) {
	encoded, ok := value.(bin.Encoder)
	if !ok {
		return nil, fmt.Errorf("tg: canonical RPC result has type %T, want bin.Encoder", value)
	}
	return encoded, nil
}

// layerRPCCanonicalTypeRefResult is the historical Handle carrier for result
// TypeRefs which had no legacy box type (for example int, string, bytes, and
// Object). Its descriptor is a generated static function table; Encode never
// walks schema metadata or uses reflection.
type layerRPCCanonicalTypeRefResult struct {
	typ   layerBoundType
	value any
}

func (r *layerRPCCanonicalTypeRefResult) Encode(b *bin.Buffer) error {
	if r == nil || r.typ.ref == nil || r.typ.encode == nil {
		return &LayerCodecError{Operation: "encode canonical RPC result", Profile: LayerProfileCanonical, Reason: "invalid canonical result TypeRef carrier"}
	}
	state := layerCodecState{}
	return layerCodecEncodeAtomic(LayerProfileCanonical, b, func() error {
		return r.typ.encode(LayerProfileCanonical, r.value, b, &state)
	})
}

// LayerRPCResult is the immutable public carrier returned by generated RPC
// dispatch. It preserves the exact admitted call for direct delivery and can
// defensively freeze the canonical handler value for retry, cache, or rewrap.
type LayerRPCResult interface {
	bin.Encoder
	Prepared() LayerPreparedCall
	WireInvariant() bool
	Freeze() (LayerFrozenResult, error)
	Prepare() (LayerPreparedResult, error)
}

// LayerRPCNext executes the admitted semantic handler with the supplied
// context. It is a one-shot capability and must not escape its consumer.
type LayerRPCNext func(context.Context) error

// LayerRPCWrapperConsumer is mandatory whenever an admitted request contains
// a transparent wrapper other than invokeWithLayer. It may inspect immutable
// wrapper metadata and replace the handler context, but cannot replace the
// handler result. It must call next synchronously and exactly once.
type LayerRPCWrapperConsumer func(context.Context, LayerRequest, LayerRPCNext) error

// LayerRPCAdmissionPreflight is invoked synchronously once for the innermost
// known terminal route, before its constructor ID or typed fields are
// consumed. Returning an error rejects admission with that exact error.
type LayerRPCAdmissionPreflight func(LayerRPCAdmissionView) error

type layerRPCUnknownMethodViewLease struct {
	active                uint32
	body                  *bin.Buffer
	approved              uint32
	approvedSemantic      LayerSemanticID
	approvedWireID        uint32
	approvedWireSize      int
	approvedWireDigest    [sha256.Size]byte
	adaptCanonical        func(*bin.Buffer) (LayerOutboundCall, error)
	adaptClientRPCOverlay func(LayerClientRPCOverlay) (*bin.Buffer, bool, error)
}

// LayerRPCUnknownMethodView is a synchronous, transactional view of an
// unknown innermost terminal method. Buffer returns a defensive private copy;
// adapter failures and unhandled results can never consume or mutate the
// caller's request. The view and returned cursor must not escape the callback
// or be accessed from another goroutine.
type LayerRPCUnknownMethodView struct {
	profile  LayerProfile
	wireID   uint32
	wireSize int
	lease    *layerRPCUnknownMethodViewLease
}

func (v LayerRPCUnknownMethodView) Profile() LayerProfile { return v.profile }
func (v LayerRPCUnknownMethodView) WireID() uint32        { return v.wireID }
func (v LayerRPCUnknownMethodView) WireSize() int         { return v.wireSize }

func (v LayerRPCUnknownMethodView) activeLease(operation string) (*layerRPCUnknownMethodViewLease, error) {
	if v.lease == nil || atomic.LoadUint32(&v.lease.active) != 1 {
		return nil, &LayerCodecError{Operation: operation, Profile: v.profile, WireID: v.wireID, Reason: "unknown method adapter view is no longer active"}
	}
	return v.lease, nil
}

// Buffer returns the one private cursor owned by this synchronous callback. A
// handled adapter must completely consume it. The cursor must not escape or be
// accessed concurrently; only the caller's original buffer is isolated by the
// defensive copy.
func (v LayerRPCUnknownMethodView) Buffer() (*bin.Buffer, error) {
	lease, err := v.activeLease("inspect unknown innermost RPC method")
	if err != nil {
		return nil, err
	}
	return lease.body, nil
}

// AdaptCanonical performs the only authoritative private-to-generated bridge.
// It admits one canonical terminal request using this dispatcher's exact field
// callbacks before materialization, then statically re-profiles it. The core
// later verifies the returned opaque call with the adapter disabled.
func (v LayerRPCUnknownMethodView) AdaptCanonical(canonical *bin.Buffer) (LayerOutboundCall, error) {
	lease, err := v.activeLease("adapt canonical unknown RPC method")
	if err != nil {
		return LayerOutboundCall{}, err
	}
	if canonical == nil {
		return LayerOutboundCall{}, &LayerCodecError{Operation: "adapt canonical unknown RPC method", Profile: v.profile, WireID: v.wireID, Reason: "nil canonical buffer"}
	}
	if lease.adaptCanonical == nil {
		return LayerOutboundCall{}, &LayerCodecError{Operation: "adapt canonical unknown RPC method", Profile: v.profile, WireID: v.wireID, Reason: "canonical bridge is unavailable"}
	}
	if !atomic.CompareAndSwapUint32(&lease.approved, 0, 2) {
		return LayerOutboundCall{}, &LayerCodecError{Operation: "adapt canonical unknown RPC method", Profile: v.profile, WireID: v.wireID, Reason: "canonical bridge may be used only once"}
	}
	outbound, err := lease.adaptCanonical(canonical)
	if err != nil {
		return LayerOutboundCall{}, err
	}
	if outbound.Profile() != v.profile || outbound.Method() == 0 || outbound.WireID() == 0 {
		return LayerOutboundCall{}, &LayerCodecError{Operation: "adapt canonical unknown RPC method", Profile: v.profile, Semantic: outbound.Method(), WireID: outbound.WireID(), Reason: "canonical bridge returned an invalid exact identity"}
	}
	var exact bin.Buffer
	if err := outbound.Encode(&exact); err != nil {
		return LayerOutboundCall{}, err
	}
	if exact.Len() == 0 {
		return LayerOutboundCall{}, &LayerCodecError{Operation: "adapt canonical unknown RPC method", Profile: v.profile, Semantic: outbound.Method(), WireID: outbound.WireID(), Reason: "canonical bridge encoded an empty exact request"}
	}
	lease.approvedSemantic = outbound.Method()
	lease.approvedWireID = outbound.WireID()
	lease.approvedWireSize = exact.Len()
	lease.approvedWireDigest = sha256.Sum256(exact.Raw())
	atomic.StoreUint32(&lease.approved, 1)
	return outbound, nil
}

// AdaptClientRPCOverlay invokes one gotdgen-compiled client-private method
// decoder against this view's exact connection profile, then passes its
// canonical value through the authoritative admission/re-profiling bridge.
// handled=false means the selected overlay does not own this constructor.
func (v LayerRPCUnknownMethodView) AdaptClientRPCOverlay(overlay LayerClientRPCOverlay) (LayerOutboundCall, bool, error) {
	lease, err := v.activeLease("adapt generated client RPC overlay")
	if err != nil {
		return LayerOutboundCall{}, true, err
	}
	if lease.adaptClientRPCOverlay == nil {
		return LayerOutboundCall{}, true, &LayerCodecError{Operation: "adapt generated client RPC overlay", Profile: v.profile, WireID: v.wireID, Reason: "generated client overlay bridge is unavailable"}
	}
	canonical, handled, err := lease.adaptClientRPCOverlay(overlay)
	if err != nil || !handled {
		return LayerOutboundCall{}, handled, err
	}
	if canonical == nil {
		return LayerOutboundCall{}, true, &LayerCodecError{Operation: "adapt generated client RPC overlay", Profile: v.profile, WireID: v.wireID, Reason: "generated client overlay returned nil canonical request"}
	}
	outbound, err := v.AdaptCanonical(canonical)
	if err != nil {
		return LayerOutboundCall{}, true, err
	}
	return outbound, true, nil
}

// LayerRPCUnknownMethodAdapter handles only an exact-profile switch miss at
// the innermost terminal. handled=false preserves ErrLayerUnknownRPCMethod.
// A handled result must come from view.AdaptCanonical.
type LayerRPCUnknownMethodAdapter func(LayerRPCUnknownMethodView) (LayerOutboundCall, bool, error)

type layerRPCAdmissionViewLease struct {
	active uint32
	body   []byte
}

// LayerRPCAdmissionView exposes bounded inspection of one terminal wire
// request without exposing the decoder's backing byte slice. Raw access is
// valid only during the synchronous preflight callback.
type LayerRPCAdmissionView struct {
	profile  LayerProfile
	semantic LayerSemanticID
	wireID   uint32
	wireSize int
	lease    *layerRPCAdmissionViewLease
}

func (v LayerRPCAdmissionView) Profile() LayerProfile     { return v.profile }
func (v LayerRPCAdmissionView) Semantic() LayerSemanticID { return v.semantic }
func (v LayerRPCAdmissionView) WireID() uint32            { return v.wireID }
func (v LayerRPCAdmissionView) WireSize() int             { return v.wireSize }

func (v LayerRPCAdmissionView) activeBody(operation string) ([]byte, error) {
	if v.lease == nil || atomic.LoadUint32(&v.lease.active) != 1 {
		return nil, &LayerCodecError{Operation: operation, Profile: v.profile, Semantic: v.semantic, WireID: v.wireID, Reason: "admission preflight view is no longer active"}
	}
	return v.lease.body, nil
}

// ByteAt returns one terminal wire byte while the callback is active.
func (v LayerRPCAdmissionView) ByteAt(offset int) (byte, error) {
	body, err := v.activeBody("inspect RPC admission byte")
	if err != nil {
		return 0, err
	}
	if offset < 0 || offset >= len(body) {
		return 0, &LayerCodecError{Operation: "inspect RPC admission byte", Profile: v.profile, Semantic: v.semantic, WireID: v.wireID, Reason: fmt.Sprintf("byte offset %d outside terminal wire size %d", offset, len(body))}
	}
	return body[offset], nil
}

// Uint32At returns one little-endian uint32 without advancing admission.
func (v LayerRPCAdmissionView) Uint32At(offset int) (uint32, error) {
	body, err := v.activeBody("inspect RPC admission uint32")
	if err != nil {
		return 0, err
	}
	if offset < 0 || offset > len(body) || len(body)-offset < 4 {
		return 0, &LayerCodecError{Operation: "inspect RPC admission uint32", Profile: v.profile, Semantic: v.semantic, WireID: v.wireID, Reason: fmt.Sprintf("uint32 offset %d outside terminal wire size %d", offset, len(body))}
	}
	return uint32(body[offset]) | uint32(body[offset+1])<<8 | uint32(body[offset+2])<<16 | uint32(body[offset+3])<<24, nil
}

// ReadAt returns a defensive copy of one bounded terminal wire range.
func (v LayerRPCAdmissionView) ReadAt(offset, length int) ([]byte, error) {
	body, err := v.activeBody("inspect RPC admission bytes")
	if err != nil {
		return nil, err
	}
	if offset < 0 || length < 0 || offset > len(body) || length > len(body)-offset {
		return nil, &LayerCodecError{Operation: "inspect RPC admission bytes", Profile: v.profile, Semantic: v.semantic, WireID: v.wireID, Reason: fmt.Sprintf("byte range [%d,%d) outside terminal wire size %d", offset, offset+length, len(body))}
	}
	copied := make([]byte, length)
	copy(copied, body[offset:offset+length])
	return copied, nil
}

type layerRPCAdmissionPreflightRunner struct {
	callback               LayerRPCAdmissionPreflight
	fields                 *layerRPCAdmissionFieldRunner
	unknownAdapter         layerRPCUnknownMethodAdapter
	profileAdmission       layerRPCProfileAdmissionMode
	admissionProfile       LayerProfile
	explicitProfile        LayerProfile
	explicitProfileSet     bool
	probedProfile          LayerProfile
	probedProfileSet       bool
	defaultWrapperReplay   bool
	adaptCanonical         func(LayerProfile, *bin.Buffer) (LayerOutboundCall, error)
	called                 uint32
	unknownAdapterActive   uint32
	unknownAdapterDisabled uint32
	suppressFieldAdmission uint32
}

func (p *layerRPCAdmissionPreflightRunner) allowDefaultWrapperFallback(current LayerProfile) bool {
	return p != nil && p.profileAdmission == layerRPCProfileDefault && !p.explicitProfileSet &&
		!p.defaultWrapperReplay && current == p.admissionProfile
}

// selectExplicitProfile applies the only runtime profile-selection rule used
// by generated transparent wrappers. In default mode exactly one explicit
// profile may replace the inherited caller default; repeated selectors must
// agree. Frozen mode preserves AdmitLayer's strict conflict behavior.
func (p *layerRPCAdmissionPreflightRunner) selectExplicitProfile(current, selected LayerProfile, semantic LayerSemanticID, wireID uint32) error {
	if p == nil {
		return &LayerCodecError{Operation: "admit RPC wrapper", Profile: current, Semantic: semantic, WireID: wireID, Reason: "nil profile admission state"}
	}
	switch p.profileAdmission {
	case layerRPCProfileFrozen:
		if current != p.admissionProfile {
			return &LayerCodecError{Operation: "admit RPC wrapper", Profile: current, Semantic: semantic, WireID: wireID, Reason: fmt.Sprintf("current profile %d differs from frozen admission profile %d", current, p.admissionProfile)}
		}
		if selected != p.admissionProfile {
			return &LayerCodecError{Operation: "admit RPC wrapper", Profile: current, Semantic: semantic, WireID: wireID, Reason: fmt.Sprintf("invokeWithLayer selected profile %d, want frozen admission profile %d", selected, p.admissionProfile)}
		}
	case layerRPCProfileDefault:
		if p.explicitProfileSet {
			if current != p.explicitProfile {
				return &LayerCodecError{Operation: "admit RPC wrapper", Profile: current, Semantic: semantic, WireID: wireID, Reason: fmt.Sprintf("current profile %d differs from explicit invokeWithLayer profile %d", current, p.explicitProfile)}
			}
			if selected != p.explicitProfile {
				return &LayerCodecError{Operation: "admit RPC wrapper", Profile: current, Semantic: semantic, WireID: wireID, Reason: fmt.Sprintf("invokeWithLayer selected profile %d, conflicts with explicit profile %d", selected, p.explicitProfile)}
			}
		} else if p.probedProfileSet {
			if current != p.probedProfile || selected != p.probedProfile {
				return &LayerCodecError{Operation: "admit RPC wrapper", Profile: current, Semantic: semantic, WireID: wireID, Reason: fmt.Sprintf("invokeWithLayer profile %d under current profile %d differs from probed profile %d", selected, current, p.probedProfile), Cause: ErrLayerProfileAmbiguous}
			}
		} else if current != p.admissionProfile {
			return &LayerCodecError{Operation: "admit RPC wrapper", Profile: current, Semantic: semantic, WireID: wireID, Reason: fmt.Sprintf("current profile %d differs from inherited admission profile %d", current, p.admissionProfile)}
		}
	default:
		return &LayerCodecError{Operation: "admit RPC wrapper", Profile: current, Semantic: semantic, WireID: wireID, Reason: "invalid profile admission mode"}
	}
	p.explicitProfile = selected
	p.explicitProfileSet = true
	return nil
}

func (p *layerRPCAdmissionPreflightRunner) run(profile LayerProfile, semantic LayerSemanticID, wireID uint32, b *bin.Buffer) error {
	if p == nil {
		return &LayerCodecError{Operation: "preflight RPC admission", Profile: profile, Semantic: semantic, WireID: wireID, Reason: "nil preflight runner"}
	}
	if !atomic.CompareAndSwapUint32(&p.called, 0, 1) {
		return &LayerCodecError{Operation: "preflight RPC admission", Profile: profile, Semantic: semantic, WireID: wireID, Reason: "terminal admission preflight ran more than once"}
	}
	if b == nil {
		return &LayerCodecError{Operation: "preflight RPC admission", Profile: profile, Semantic: semantic, WireID: wireID, Reason: "nil terminal wire buffer"}
	}
	if atomic.LoadUint32(&p.suppressFieldAdmission) == 0 {
		if err := p.fields.begin(profile, semantic, wireID); err != nil {
			return err
		}
	}
	if p.callback == nil {
		return nil
	}
	body := b.Raw()
	lease := &layerRPCAdmissionViewLease{active: 1, body: body}
	view := LayerRPCAdmissionView{profile: profile, semantic: semantic, wireID: wireID, wireSize: len(body), lease: lease}
	defer atomic.StoreUint32(&lease.active, 0)
	return p.callback(view)
}

type layerRPCServerResult struct {
	prepared        LayerPreparedCall
	value           any
	canonicalResult layerRPCCanonicalResultEncoder
}

func (r *layerRPCServerResult) Prepared() LayerPreparedCall {
	if r == nil {
		return LayerPreparedCall{}
	}
	return r.prepared
}

func (r *layerRPCServerResult) WireInvariant() bool {
	return r != nil && r.prepared.Call().WireInvariant()
}

func (r *layerRPCServerResult) Freeze() (LayerFrozenResult, error) {
	if r == nil {
		return LayerFrozenResult{}, errors.New("can't freeze nil layer RPC result")
	}
	return r.prepared.Call().FreezeResult(r.value)
}

func (r *layerRPCServerResult) Prepare() (LayerPreparedResult, error) {
	if r == nil {
		return LayerPreparedResult{}, errors.New("can't prepare nil layer RPC result")
	}
	return r.prepared.Call().prepareResult(r.value)
}

func (r *layerRPCServerResult) encodeCanonicalResult() (bin.Encoder, error) {
	if r == nil {
		return nil, errors.New("can't encode nil canonical layer RPC result")
	}
	if r.canonicalResult == nil {
		return nil, &LayerCodecError{Operation: "encode canonical RPC result", Profile: r.prepared.Call().Profile(), Semantic: r.prepared.Call().Method(), WireID: r.prepared.Call().WireID(), Reason: "canonical result adapter is not registered"}
	}
	return r.canonicalResult(r.value)
}

// Encode uses the immutable call descriptor captured at admission. RPC
// results therefore use the same generated bound codec core as EncodeLayer
// and can never observe a later session-layer change.
func (r *layerRPCServerResult) Encode(b *bin.Buffer) error {
	if r == nil {
		return errors.New("can't encode nil layer RPC result")
	}
	return r.prepared.Call().EncodeResult(r.value, b)
}

var _ LayerRPCResult = (*layerRPCServerResult)(nil)

type ServerDispatcher struct {
	fallback                     func(ctx context.Context, b *bin.Buffer) (bin.Encoder, error)
	handlers                     map[LayerSemanticID]layerRPCRegisteredHandler
	wrapperConsumer              LayerRPCWrapperConsumer
	admissionPreflight           LayerRPCAdmissionPreflight
	admissionFieldPreflights     []LayerRPCAdmissionFieldPreflight
	admissionFieldPreflightCount int
	unknownMethodAdapter         layerRPCUnknownMethodAdapter
}

func NewServerDispatcher(fallback func(ctx context.Context, b *bin.Buffer) (bin.Encoder, error)) *ServerDispatcher {
	return &ServerDispatcher{
		fallback: fallback,
		handlers: make(map[LayerSemanticID]layerRPCRegisteredHandler),
	}
}

// OnLayerRPCAdmissionFieldPreflight registers one generated canonical field
// metric. Registration fails closed unless every routable profile exposes the
// same metric directly; unavailable methods are the only accepted absence.
// Register callbacks before serving concurrent admissions.
func (s *ServerDispatcher) OnLayerRPCAdmissionFieldPreflight(fieldID LayerRPCFieldID, callback LayerRPCAdmissionFieldPreflight) error {
	if s == nil {
		return fmt.Errorf("tg: register layer RPC admission field preflight on nil ServerDispatcher")
	}
	if callback == nil {
		return fmt.Errorf("tg: register nil layer RPC admission field preflight")
	}
	index, err := layerRPCAdmissionFieldRegistration(fieldID)
	if err != nil {
		return err
	}
	if s.admissionFieldPreflights == nil {
		s.admissionFieldPreflights = make([]LayerRPCAdmissionFieldPreflight, layerRPCAdmissionFieldCount)
	}
	if index < 0 || index >= len(s.admissionFieldPreflights) {
		return fmt.Errorf("tg: generated layer RPC admission field index %d is out of range", index)
	}
	if s.admissionFieldPreflights[index] != nil {
		return fmt.Errorf("tg: duplicate layer RPC admission field preflight for %#016x", uint64(fieldID))
	}
	s.admissionFieldPreflights[index] = callback
	s.admissionFieldPreflightCount++
	return nil
}

// OnLayerRPCWrappers registers the single owner of wrapper semantics such as
// invokeAfterMsg(s), invokeWithoutUpdates, takeout, message ranges, and
// initConnection. invokeWithLayer itself is consumed by exact admission.
func (s *ServerDispatcher) OnLayerRPCWrappers(consumer LayerRPCWrapperConsumer) {
	if s == nil {
		panic("tg: register layer RPC wrapper consumer on nil ServerDispatcher")
	}
	if consumer == nil {
		panic("tg: register nil layer RPC wrapper consumer")
	}
	if s.wrapperConsumer != nil {
		panic("tg: duplicate layer RPC wrapper consumer")
	}
	s.wrapperConsumer = consumer
}

// OnLayerRPCAdmissionPreflight registers the single synchronous admission
// guard. It observes only the innermost known terminal route and runs before
// that route performs any typed decode or allocation.
func (s *ServerDispatcher) OnLayerRPCAdmissionPreflight(callback LayerRPCAdmissionPreflight) {
	if s == nil {
		panic("tg: register layer RPC admission preflight on nil ServerDispatcher")
	}
	if callback == nil {
		panic("tg: register nil layer RPC admission preflight")
	}
	if s.admissionPreflight != nil {
		panic("tg: duplicate layer RPC admission preflight")
	}
	s.admissionPreflight = callback
}

// OnLayerRPCUnknownMethod registers the single private-schema extension point.
// Generated official routes always take precedence; the callback is reachable
// only after all known transparent wrappers have been recursively peeled.
func (s *ServerDispatcher) OnLayerRPCUnknownMethod(callback LayerRPCUnknownMethodAdapter) {
	if s == nil {
		panic("tg: register unknown layer RPC method adapter on nil ServerDispatcher")
	}
	if callback == nil {
		panic("tg: register nil unknown layer RPC method adapter")
	}
	if s.unknownMethodAdapter != nil {
		panic("tg: duplicate unknown layer RPC method adapter")
	}
	s.unknownMethodAdapter = func(view LayerRPCUnknownMethodView) (layerRPCUnknownMethodResult, bool, error) {
		outbound, handled, err := callback(view)
		if err != nil || !handled {
			return layerRPCUnknownMethodResult{}, handled, err
		}
		return layerRPCUnknownMethodResult{
			profile:  outbound.Profile(),
			semantic: outbound.Method(),
			wireID:   outbound.WireID(),
			encode:   outbound.Encode,
		}, true, nil
	}
}

// register preserves the existing OnX facade while rejecting accidental
// duplicate ownership of one semantic method. Multiple layer wire IDs do not
// create multiple registrations.
func (s *ServerDispatcher) register(method LayerSemanticID, handler layerRPCHandler, canonicalResult layerRPCCanonicalResultEncoder) {
	if s == nil {
		panic("tg: register layer RPC handler on nil ServerDispatcher")
	}
	if handler == nil {
		panic("tg: register nil layer RPC handler")
	}
	if canonicalResult == nil {
		panic("tg: register nil canonical layer RPC result encoder")
	}
	if _, duplicate := s.handlers[method]; duplicate {
		category, qname, _ := LayerSemanticName(method)
		panic(fmt.Sprintf("tg: duplicate layer RPC handler for %s:%s", category, qname))
	}
	s.handlers[method] = layerRPCRegisteredHandler{invoke: handler, canonicalResult: canonicalResult}
}

// HasLayerRPCHandler reports whether an admitted semantic method has a
// complete registered handler. It is nil-safe and does not mutate dispatcher
// state, so callers can trace known-but-unimplemented RPCs before dispatch.
func (s *ServerDispatcher) HasLayerRPCHandler(semantic LayerSemanticID) bool {
	if s == nil {
		return false
	}
	handler, ok := s.handlers[semantic]
	return ok && handler.invoke != nil && handler.canonicalResult != nil
}

// Handle retains the historical canonical ServerDispatcher API, including
// established concrete/class/Bool/vector result boxes. Result TypeRefs which
// never had a legacy box return a private bin.Encoder backed by the generated
// canonical descriptor. New exact-profile callers should use AdmitLayer and
// DispatchAdmitted (or HandleLayer) and keep the frozen TypeRef.
func (s *ServerDispatcher) Handle(ctx context.Context, b *bin.Buffer) (bin.Encoder, error) {
	encoded, err := s.HandleLayer(LayerProfileCanonical, ctx, b)
	if err != nil {
		return nil, err
	}
	result, ok := encoded.(*layerRPCServerResult)
	if !ok {
		return encoded, nil
	}
	return result.encodeCanonicalResult()
}

func prepareLayerRPCRequest(profile LayerProfile, b *bin.Buffer, limits LayerDecodeLimits, callback LayerRPCAdmissionPreflight, fieldCallbacks []LayerRPCAdmissionFieldPreflight, unknownAdapter layerRPCUnknownMethodAdapter, profileAdmission layerRPCProfileAdmissionMode) (LayerRequest, error) {
	if b == nil {
		return LayerRequest{}, &LayerCodecError{Operation: "prepare RPC request", Profile: profile, Reason: "nil buffer"}
	}
	wireRequest := b.Raw()
	working := *b
	decoded, err := decodeLayerRPCRequest(profile, &working, limits, callback, fieldCallbacks, unknownAdapter, profileAdmission)
	if err != nil {
		return LayerRequest{}, err
	}
	if working.Len() != 0 {
		return LayerRequest{}, &LayerCodecError{Operation: "prepare RPC request", Profile: decoded.call.Profile(), Semantic: decoded.call.Method(), WireID: decoded.call.WireID(), Reason: fmt.Sprintf("%d trailing request bytes", working.Len())}
	}
	if len(wireRequest) == 0 || decoded.request == nil {
		return LayerRequest{}, &LayerCodecError{Operation: "prepare RPC request", Profile: decoded.call.Profile(), Semantic: decoded.call.Method(), WireID: decoded.call.WireID(), Reason: "empty wire request or nil canonical request"}
	}
	semanticIdentity := decoded.semanticIdentity
	if !semanticIdentity.valid || semanticIdentity.requestType == nil ||
		semanticIdentity.method != decoded.call.Method() || semanticIdentity.requestType.method != decoded.call.Method() ||
		semanticIdentity.requestType.canonicalWireID == 0 {
		return LayerRequest{}, &LayerCodecError{Operation: "prepare RPC request", Profile: decoded.call.Profile(), Semantic: decoded.call.Method(), WireID: decoded.call.WireID(), Reason: "invalid innermost semantic request identity"}
	}
	wrappers := make([]LayerRPCWrapper, len(decoded.wrappers))
	for index := range decoded.wrappers {
		wrappers[len(decoded.wrappers)-1-index] = decoded.wrappers[index]
	}
	prepared := LayerPreparedCall{
		call:             decoded.call,
		wireSize:         len(wireRequest),
		wireDigest:       sha256.Sum256(wireRequest),
		semanticIdentity: semanticIdentity,
	}
	*b = working
	return LayerRequest{
		lease:                  &layerRPCRequestLease{request: decoded.request},
		prepared:               prepared,
		wrappers:               wrappers,
		profileEvidenceProfile: decoded.explicitProfile,
		profileEvidence:        decoded.profileEvidence,
	}, nil
}

func layerValidateRPCRequestLease(admitted LayerRequest, operation string) (*layerRPCRequestLease, error) {
	lease := admitted.lease
	prepared := admitted.Prepared()
	call := admitted.Call()
	if lease == nil || lease.request == nil || prepared.wireSize <= 0 || prepared.call.Identity() != call.Identity() ||
		!prepared.semanticIdentity.valid || prepared.semanticIdentity.requestType == nil ||
		prepared.semanticIdentity.method != call.Method() || prepared.semanticIdentity.requestType.method != call.Method() ||
		call.canonicalResult == nil || call.wireResult == nil || call.canonical.ref == nil || call.result.ref == nil {
		return nil, &LayerCodecError{Operation: operation, Profile: call.Profile(), Semantic: call.Method(), WireID: call.WireID(), Reason: "invalid or zero prepared admission"}
	}
	if admitted.effectiveProfileKnown && admitted.effectiveProfile != call.Profile() {
		return nil, &LayerCodecError{Operation: operation, Profile: call.Profile(), Semantic: call.Method(), WireID: call.WireID(), Reason: "effective profile differs from the frozen terminal call"}
	}
	if admitted.profileEvidence && (!admitted.effectiveProfileKnown || admitted.profileEvidenceProfile != admitted.effectiveProfile) {
		return nil, &LayerCodecError{Operation: operation, Profile: call.Profile(), Semantic: call.Method(), WireID: call.WireID(), Reason: "profile evidence differs from the effective terminal profile"}
	}
	return lease, nil
}

// PrepareOutbound atomically converts an admitted terminal canonical request
// into one opaque exact-profile outbound call. It never exposes the canonical
// request object. A successful conversion consumes the shared admission lease,
// so no value-copy can subsequently dispatch or reprofile the same request.
// Wrappers are rejected because reducing them to a terminal call would discard
// wrapper-specific side effects and ordering semantics.
func (r LayerRequest) PrepareOutbound(profile LayerProfile) (LayerOutboundCall, error) {
	call := r.Call()
	lease, err := layerValidateRPCRequestLease(r, "prepare admitted RPC outbound call")
	if err != nil {
		return LayerOutboundCall{}, err
	}
	if len(r.wrappers) != 0 {
		return LayerOutboundCall{}, &LayerCodecError{Operation: "prepare admitted RPC outbound call", Profile: call.Profile(), Semantic: call.Method(), WireID: call.WireID(), Reason: "transparent RPC wrappers cannot be discarded while reprofiling"}
	}
	outbound, err := PrepareLayerOutboundCall(profile, lease.request)
	if err != nil {
		return LayerOutboundCall{}, err
	}
	if outbound.Profile() != profile || outbound.Method() != call.Method() || outbound.WireID() == 0 {
		return LayerOutboundCall{}, &LayerCodecError{Operation: "prepare admitted RPC outbound call", Profile: profile, Semantic: call.Method(), WireID: outbound.WireID(), Reason: "outbound semantic identity does not match admitted request"}
	}
	if !atomic.CompareAndSwapUint32(&lease.consumed, 0, 1) {
		return LayerOutboundCall{}, &LayerCodecError{Operation: "prepare admitted RPC outbound call", Profile: profile, Semantic: call.Method(), WireID: outbound.WireID(), Reason: "admission lease was already consumed"}
	}
	return outbound, nil
}

// AdmitLayer decodes and completely consumes one request using an already
// frozen exact profile. An explicit invokeWithLayer must select that same
// profile; it cannot mutate a live connection's profile.
func (s *ServerDispatcher) AdmitLayer(profile LayerProfile, b *bin.Buffer) (LayerRequest, error) {
	return s.AdmitLayerWithLimits(profile, b, LayerDecodeLimits{})
}

// AdmitLayerWithLimits is AdmitLayer with one request-scoped bounded decode
// budget. Limits are initialized before any wrapper or terminal typed decode.
func (s *ServerDispatcher) AdmitLayerWithLimits(profile LayerProfile, b *bin.Buffer, limits LayerDecodeLimits) (LayerRequest, error) {
	admitted, err := s.admitLayerProfile(profile, b, limits, layerRPCProfileFrozen)
	if err != nil {
		return LayerRequest{}, err
	}
	admitted.effectiveProfile = admitted.Call().Profile()
	admitted.effectiveProfileKnown = true
	admitted.profileEvidenceProfile = profile
	admitted.profileEvidence = true
	return admitted, nil
}

// AdmitDefaultLayer decodes a request using an inherited caller default.
// Naked requests keep that default. The first invokeWithLayer found anywhere
// in the generated transparent wrapper chain overrides it and becomes explicit
// profile evidence; subsequent selectors must agree with that profile.
func (s *ServerDispatcher) AdmitDefaultLayer(defaultProfile LayerProfile, b *bin.Buffer) (LayerRequest, error) {
	return s.AdmitDefaultLayerWithLimits(defaultProfile, b, LayerDecodeLimits{})
}

// AdmitDefaultLayerWithLimits is AdmitDefaultLayer with one request-scoped
// bounded decode budget. Unlike AdmitLayer, its caller profile is inherited
// fallback state rather than frozen client evidence.
func (s *ServerDispatcher) AdmitDefaultLayerWithLimits(defaultProfile LayerProfile, b *bin.Buffer, limits LayerDecodeLimits) (LayerRequest, error) {
	admitted, err := s.admitLayerProfile(defaultProfile, b, limits, layerRPCProfileDefault)
	if err != nil {
		return LayerRequest{}, err
	}
	admitted.effectiveProfile = admitted.Call().Profile()
	admitted.effectiveProfileKnown = true
	return admitted, nil
}

func (s *ServerDispatcher) admitLayerProfile(profile LayerProfile, b *bin.Buffer, limits LayerDecodeLimits, profileAdmission layerRPCProfileAdmissionMode) (LayerRequest, error) {
	if s == nil {
		return LayerRequest{}, &LayerCodecError{Operation: "admit RPC request", Profile: profile, Reason: "nil ServerDispatcher"}
	}
	if _, ok := ResolveLayerProfile(int(profile)); !ok {
		return LayerRequest{}, &LayerCodecError{Operation: "admit RPC request", Profile: profile, Reason: "unsupported exact profile"}
	}
	var fieldCallbacks []LayerRPCAdmissionFieldPreflight
	if s.admissionFieldPreflightCount != 0 {
		fieldCallbacks = s.admissionFieldPreflights
	}
	return prepareLayerRPCRequest(profile, b, limits, s.admissionPreflight, fieldCallbacks, s.unknownMethodAdapter, profileAdmission)
}

// AdmitUnprofiled accepts invariant invokeWithLayer with explicit profile
// evidence and generation-time proven invariant terminal methods without
// profile evidence. The latter do not declare or freeze a client layer.
func (s *ServerDispatcher) AdmitUnprofiled(b *bin.Buffer) (LayerRequest, error) {
	return s.AdmitUnprofiledWithLimits(b, LayerDecodeLimits{})
}

// AdmitUnprofiledWithLimits uses one request-scoped decode budget for complete
// admission. Invariant terminal methods are decoded through the canonical
// static route only after generation proved that route wire-identical across
// all profiles; ProfileEvidence remains absent for those requests.
func (s *ServerDispatcher) AdmitUnprofiledWithLimits(b *bin.Buffer, limits LayerDecodeLimits) (LayerRequest, error) {
	if s == nil {
		return LayerRequest{}, &LayerCodecError{Operation: "admit unprofiled RPC request", Reason: "nil ServerDispatcher"}
	}
	profile, profileEvidence, err := decodeUnprofiledLayerProfile(b)
	if err != nil {
		return LayerRequest{}, err
	}
	admitted, err := s.admitLayerProfile(profile, b, limits, layerRPCProfileFrozen)
	if err != nil {
		return LayerRequest{}, err
	}
	if admitted.profileEvidence != profileEvidence {
		return LayerRequest{}, &LayerCodecError{Operation: "admit unprofiled RPC request", Profile: admitted.Call().Profile(), Semantic: admitted.Call().Method(), WireID: admitted.Call().WireID(), Reason: "profile probe and exact admission evidence disagree"}
	}
	if profileEvidence {
		admitted.effectiveProfile = admitted.Call().Profile()
		admitted.effectiveProfileKnown = true
	} else {
		admitted.profileEvidenceProfile = LayerProfile(0)
		admitted.profileEvidence = false
	}
	return admitted, nil
}

func layerRPCNeedsWrapperConsumer(admitted LayerRequest) bool {
	for index := range admitted.wrappers {
		if admitted.wrappers[index].semantic != LayerSemanticMethodInvokeWithLayer {
			return true
		}
	}
	return false
}

// DispatchAdmitted atomically consumes one immutable admission lease. Value
// copies share that lease, so the same request can never execute twice. A
// successful dispatch retains the handler's raw typed value; boxing and exact
// profile conversion happen only when the returned LayerRPCResult is encoded.
func (s *ServerDispatcher) DispatchAdmitted(ctx context.Context, admitted LayerRequest) (LayerRPCResult, error) {
	if s == nil {
		return nil, &LayerCodecError{Operation: "dispatch admitted RPC", Reason: "nil ServerDispatcher"}
	}
	prepared := admitted.Prepared()
	call := admitted.Call()
	lease, err := layerValidateRPCRequestLease(admitted, "dispatch admitted RPC")
	if err != nil {
		return nil, err
	}
	handler, ok := s.handlers[call.Method()]
	if !ok || handler.invoke == nil || handler.canonicalResult == nil {
		return nil, &LayerCodecError{Operation: "dispatch admitted RPC", Profile: call.Profile(), Semantic: call.Method(), WireID: call.WireID(), Reason: "RPC handler is not registered"}
	}
	needsConsumer := layerRPCNeedsWrapperConsumer(admitted)
	if needsConsumer && s.wrapperConsumer == nil {
		return nil, &LayerCodecError{Operation: "dispatch admitted RPC wrappers", Profile: call.Profile(), Semantic: call.Method(), WireID: call.WireID(), Reason: "non-layer RPC wrappers require a registered consumer"}
	}
	if !atomic.CompareAndSwapUint32(&lease.consumed, 0, 1) {
		return nil, &LayerCodecError{Operation: "dispatch admitted RPC", Profile: call.Profile(), Semantic: call.Method(), WireID: call.WireID(), Reason: "admission lease was already consumed"}
	}

	var result LayerRPCResult
	invoke := func(handlerCtx context.Context) error {
		if handlerCtx == nil {
			return &LayerCodecError{Operation: "dispatch admitted RPC", Profile: call.Profile(), Semantic: call.Method(), WireID: call.WireID(), Reason: "nil handler context"}
		}
		value, err := handler.invoke(handlerCtx, lease.request)
		if err != nil {
			return err
		}
		result = &layerRPCServerResult{prepared: prepared, value: value, canonicalResult: handler.canonicalResult}
		return nil
	}
	if !needsConsumer {
		if err := invoke(ctx); err != nil {
			return nil, err
		}
		return result, nil
	}

	var attempts uint32
	var consumerReturned uint32
	var invokeErr error
	done := make(chan struct{})
	next := func(nextCtx context.Context) error {
		attempt := atomic.AddUint32(&attempts, 1)
		if attempt != 1 {
			return &LayerCodecError{Operation: "dispatch admitted RPC wrappers", Profile: call.Profile(), Semantic: call.Method(), WireID: call.WireID(), Reason: "wrapper consumer called next more than once"}
		}
		defer close(done)
		if atomic.LoadUint32(&consumerReturned) != 0 {
			invokeErr = &LayerCodecError{Operation: "dispatch admitted RPC wrappers", Profile: call.Profile(), Semantic: call.Method(), WireID: call.WireID(), Reason: "wrapper consumer let next escape its synchronous call"}
			return invokeErr
		}
		invokeErr = invoke(nextCtx)
		if atomic.LoadUint32(&consumerReturned) != 0 {
			invokeErr = &LayerCodecError{Operation: "dispatch admitted RPC wrappers", Profile: call.Profile(), Semantic: call.Method(), WireID: call.WireID(), Reason: "wrapper consumer returned before next completed", Cause: invokeErr}
		}
		return invokeErr
	}
	consumerErr := s.wrapperConsumer(ctx, admitted, next)
	atomic.StoreUint32(&consumerReturned, 1)
	attemptCount := atomic.LoadUint32(&attempts)
	if attemptCount != 1 {
		if attemptCount != 0 {
			<-done
		}
		return nil, &LayerCodecError{Operation: "dispatch admitted RPC wrappers", Profile: call.Profile(), Semantic: call.Method(), WireID: call.WireID(), Reason: fmt.Sprintf("wrapper consumer called next %d times, want exactly once", attemptCount), Cause: consumerErr}
	}
	<-done
	if invokeErr != nil {
		return nil, invokeErr
	}
	if consumerErr != nil {
		return nil, consumerErr
	}
	if result == nil {
		return nil, &LayerCodecError{Operation: "dispatch admitted RPC wrappers", Profile: call.Profile(), Semantic: call.Method(), WireID: call.WireID(), Reason: "wrapper consumer completed without a handler result"}
	}
	return result, nil
}

// HandleLayer is the compatibility convenience path for a connection whose
// exact profile is already frozen. A known generated route returns a
// LayerRPCResult carrying that admission's exact result TypeRef; it never
// converts the value to Handle's legacy canonical box. Unknown top-level IDs
// may use fallback, while known IDs never bypass generated admission.
func (s *ServerDispatcher) HandleLayer(profile LayerProfile, ctx context.Context, b *bin.Buffer) (bin.Encoder, error) {
	if _, ok := ResolveLayerProfile(int(profile)); !ok {
		return nil, &LayerCodecError{Operation: "decode request", Profile: profile, Reason: "unsupported exact profile"}
	}
	if b == nil {
		return nil, &LayerCodecError{Operation: "decode request", Profile: profile, Reason: "nil buffer"}
	}
	id, err := b.PeekID()
	if err != nil {
		return nil, err
	}
	if _, ok := LayerSemanticForWireID(profile, id); !ok {
		if s.fallback == nil {
			return nil, &LayerCodecError{Operation: "decode request", Profile: profile, WireID: id, Reason: "unknown RPC method", Cause: ErrLayerUnknownRPCMethod}
		}
		return s.fallback(ctx, b)
	}
	admitted, err := s.AdmitLayer(profile, b)
	if err != nil {
		return nil, err
	}
	result, err := s.DispatchAdmitted(ctx, admitted)
	if err != nil {
		return nil, err
	}
	return result, nil
}

// HandleUnprofiled is the compatibility convenience for a first request.
// Generated invariant terminals and invokeWithLayer are admitted; unknown IDs
// may use fallback.
func (s *ServerDispatcher) HandleUnprofiled(ctx context.Context, b *bin.Buffer) (bin.Encoder, error) {
	if b == nil {
		return nil, &LayerCodecError{Operation: "decode unprofiled request", Reason: "nil buffer"}
	}
	id, err := b.PeekID()
	if err != nil {
		return nil, err
	}
	if !isUnprofiledLayerRPCWireID(id) {
		if s != nil && s.fallback != nil {
			return s.fallback(ctx, b)
		}
		if isGeneratedLayerRPCWireID(id) {
			return nil, &LayerCodecError{Operation: "decode unprofiled request", WireID: id, Reason: "known RPC requires a default profile or explicit invokeWithLayer", Cause: ErrLayerProfileRequired}
		}
		return nil, &LayerCodecError{Operation: "decode unprofiled request", WireID: id, Reason: "unknown RPC constructor", Cause: ErrLayerUnknownRPCMethod}
	}
	admitted, err := s.AdmitUnprofiled(b)
	if err != nil {
		return nil, err
	}
	result, err := s.DispatchAdmitted(ctx, admitted)
	if err != nil {
		return nil, err
	}
	return result, nil
}

func (s *ServerDispatcher) OnAccountAcceptAuthorization(f func(ctx context.Context, request *AccountAcceptAuthorizationRequest) (bool, error)) {
	s.register(LayerSemanticMethodAccountAcceptAuthorization, func(ctx context.Context, object bin.Object) (any, error) {
		typed, ok := object.(*AccountAcceptAuthorizationRequest)
		if !ok {
			return nil, fmt.Errorf("tg: admitted account.acceptAuthorization request has type %T", object)
		}
		request := *typed
		_ = request
		response, err := f(ctx, &request)
		if err != nil {
			return nil, err
		}
		return response, nil
	}, func(value any) (bin.Encoder, error) {
		response, ok := value.(bool)
		if !ok {
			return nil, fmt.Errorf("tg: canonical account.acceptAuthorization result has type %T, want bool", value)
		}
		if response {
			return &BoolBox{Bool: &BoolTrue{}}, nil
		}
		return &BoolBox{Bool: &BoolFalse{}}, nil
	})
}

